\title{Extremal Determinants of $4 \times 4$ Integer Matrices \\ with Bounded Entries}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
We study the maximal determinant problem for $4 \times 4$ integer matrices whose
entries lie in a symmetric range $\{-B, \dots, B\}$. We give an explicit
construction --- a scaled order-$4$ Hadamard matrix --- whose entries are all
$\pm B$, whose rows are mutually orthogonal, and whose determinant equals
$16\,B^4$. Using the Leibniz expansion we establish the universal permutation
bound $|\det A| \le 24\,B^4$ for every admissible matrix. Together these bracket
the maximum determinant $M(B)$ as $16\,B^4 \le M(B) \le 24\,B^4$, with the lower
bound attained. We show the orthogonality relation $A A^{\T} = 4B^2 I$ certifies
$(\det A)^2 = (4B^2)^4$, and we identify the exact value $M(B) = 16\,B^4$,
observing that closing the bracket from $24$ to $16$ is exactly the Hadamard
determinant inequality. Finally, we refute a previously circulated candidate:
the expression $(2k-1)^4 - 2(2k-1)^2 + 1$, once proposed as the maximum over the
odd-radius range $\{-(2k-1), \dots, 2k-1\}$, is not even an upper bound --- for
every $k \ge 1$ the explicit construction exceeds it, and at $k = 1$ the formula
gives $0$ while the true maximum is $16$.
\end{abstract}

\maketitle

\section{Introduction}

Given a bound $B \ge 0$, consider the integer matrices whose entries lie in the
symmetric range $\{-B, -B+1, \dots, B-1, B\}$. Over this family, how large can the
determinant be? This is a finite-order instance of the classical \emph{maximal
determinant problem}, which dates to Hadamard's work of the 1890s and remains open
in general owing to its link with the existence of Hadamard matrices.

We focus on order $4$, the smallest order at which a nontrivial Hadamard matrix
exists. Our contributions are: an explicit extremal construction with determinant
$16\,B^4$ (Section~\ref{sec:construction}); a universal permutation bound
$|\det A| \le 24\,B^4$ (Section~\ref{sec:upper}); a rigorous bracket
$16\,B^4 \le M(B) \le 24\,B^4$ with the exact value identified
(Section~\ref{sec:bracket}); and a refutation of a circulated candidate formula
(Section~\ref{sec:refute}).

Throughout, $A^{\T}$ denotes the transpose, $I$ the $4 \times 4$ identity, and
$\det A$ the determinant. Rows and columns are indexed by $\{0,1,2,3\}$.

\section{Preliminaries and definitions}

\begin{definition}[Admissible family]
For $B \ge 0$, a matrix $A \in \Z^{4 \times 4}$ is \emph{$B$-admissible} if
$|A_{ij}| \le B$ for all $i,j$. Write $\Amdl(B)$ for the set of $B$-admissible
matrices and set $M(B) := \max_{A \in \Amdl(B)} \det A$, a maximum over a finite
nonempty set.
\end{definition}

\begin{definition}[Cofactor expansion]
For a $4 \times 4$ matrix $M$ over a commutative ring, expansion along the first
row gives
\begin{align*}
\det M
&= M_{00}\big(M_{11}(M_{22}M_{33} - M_{23}M_{32}) - M_{12}(M_{21}M_{33} - M_{23}M_{31}) + M_{13}(M_{21}M_{32} - M_{22}M_{31})\big) \\
&\quad - M_{01}\big(M_{10}(M_{22}M_{33} - M_{23}M_{32}) - M_{12}(M_{20}M_{33} - M_{23}M_{30}) + M_{13}(M_{20}M_{32} - M_{22}M_{30})\big) \\
&\quad + M_{02}\big(M_{10}(M_{21}M_{33} - M_{23}M_{31}) - M_{11}(M_{20}M_{33} - M_{23}M_{30}) + M_{13}(M_{20}M_{31} - M_{21}M_{30})\big) \\
&\quad - M_{03}\big(M_{10}(M_{21}M_{32} - M_{22}M_{31}) - M_{11}(M_{20}M_{32} - M_{22}M_{30}) + M_{12}(M_{20}M_{31} - M_{21}M_{30})\big).
\end{align*}
\end{definition}

\paragraph{Geometric interpretation.}
Writing the rows of $A$ as vectors $r_0,\dots,r_3 \in \R^4$, the quantity
$|\det A|$ is the $4$-dimensional volume of the parallelepiped they span. Each
edge length satisfies $\|r_i\|^2 = \sum_j A_{ij}^2 \le 4B^2$, maximized at
$\|r_i\| = 2B$ when every entry is $\pm B$; and for edges of fixed length the
volume is maximized when they are mutually orthogonal. This predicts a maximum
volume $(2B)^4 = 16\,B^4$.

\section{The extremal construction}
\label{sec:construction}

\begin{definition}[Scaled Hadamard matrix]
For $B \in \Z$ define
\[
H(B) :=
\begin{pmatrix}
 B & B & B & B \\
 B & -B & B & -B \\
 B & B & -B & -B \\
 B & -B & -B & B
\end{pmatrix}.
\]
\end{definition}

\begin{proposition}[Entries]
Every entry of $H(B)$ satisfies $|H(B)_{ij}| = |B|$; in particular, for $B \ge 0$
we have $H(B) \in \Amdl(B)$.
\end{proposition}

\begin{proof}
Each entry is $+B$ or $-B$, so has absolute value $|B|$; for $B \ge 0$ this is
$\le B$.
\end{proof}

\begin{theorem}[Orthogonality certificate]
\label{thm:ortho}
The rows of $H(B)$ are mutually orthogonal of equal squared length $4B^2$;
equivalently $H(B)\,H(B)^{\T} = 4B^2\,I$.
\end{theorem}

\begin{proof}
The $(i,j)$ entry of $H(B)H(B)^{\T}$ is the dot product of rows $i$ and $j$. For
$i=j$ it equals $4B^2$; for $i \ne j$ a direct check gives $0$ (e.g. rows $0,1$:
$B^2 - B^2 + B^2 - B^2 = 0$).
\end{proof}

\begin{theorem}[Extremal determinant]
\label{thm:det}
$\det H(B) = 16\,B^4$.
\end{theorem}

\begin{proof}
The cofactor expansion simplifies to $16\,B^4$. Alternatively, by
Theorem~\ref{thm:ortho} and $\det(XY)=\det X \det Y$, $\det X^{\T} = \det X$,
\[
(\det H(B))^2 = \det\!\big(H(B) H(B)^{\T}\big) = \det(4B^2 I) = (4B^2)^4 = 256\,B^8,
\]
so $|\det H(B)| = 16\,B^4$; the direct expansion fixes the sign as $+$.
\end{proof}

\begin{remark}[Scaling]
Since $\det(c\cdot M) = c^4 \det M$ in order $4$ and $H(B) = B\cdot H(1)$ with
$\det H(1) = 16$, we recover $\det H(B) = 16\,B^4$.
\end{remark}

\section{Upper bounds via the permutation expansion}
\label{sec:upper}

\begin{theorem}[Leibniz bound]
\label{thm:leibniz}
If $A \in \Z^{n \times n}$ has $|A_{ij}| \le B$ for all $i,j$, then
$|\det A| \le n!\,B^n$.
\end{theorem}

\begin{proof}
By the Leibniz formula $\det A = \sum_{\sigma \in S_n} \operatorname{sgn}(\sigma)
\prod_i A_{i\,\sigma(i)}$, a sum of $n!$ products each of magnitude $\le B^n$; the
triangle inequality finishes.
\end{proof}

\begin{corollary}[Order-$4$ permutation bound]
\label{cor:24}
Every $B$-admissible $4 \times 4$ matrix satisfies $|\det A| \le 24\,B^4$, hence
$\det A \le 24\,B^4$.
\end{corollary}

\begin{proof}
Theorem~\ref{thm:leibniz} with $n = 4$ and $4! = 24$.
\end{proof}

The permutation bound is valid but loose: it treats all $24$ signed products as if
they could jointly attain magnitude $B^4$ with a common sign.

\section{The maximum, bracketed and identified}
\label{sec:bracket}

\begin{theorem}[Lower bound]
For $B \ge 0$ there is a $B$-admissible matrix of determinant $16\,B^4$; hence
$M(B) \ge 16\,B^4$.
\end{theorem}

\begin{proof}
Take $A = H(B)$ and apply Theorem~\ref{thm:det}.
\end{proof}

\begin{theorem}[Upper bound]
For $B \ge 0$, $M(B) \le 24\,B^4$.
\end{theorem}

\begin{proof}
Corollary~\ref{cor:24} applied to the maximizer.
\end{proof}

\begin{theorem}[Bracket]
For $B \ge 0$, $16\,B^4 \le M(B) \le 24\,B^4$, with the lower end attained by
$H(B)$.
\end{theorem}

\begin{theorem}[Exact value]
\label{thm:exact}
In fact $M(B) = 16\,B^4$.
\end{theorem}

\begin{proof}[Sketch]
Set $G = A A^{\T}$, positive semidefinite with $G_{ii} = \|r_i\|^2 \le 4B^2$. The
Hadamard determinant inequality $\det G \le \prod_i G_{ii}$ gives
$(\det A)^2 = \det G \le (4B^2)^4 = 256\,B^8$, so $|\det A| \le 16\,B^4$; equality
forces orthogonal $\pm B$ rows, i.e. a scaled Hadamard matrix.
\end{proof}

\begin{remark}[Where the gap lives]
Sharpening the elementary $24\,B^4$ to $16\,B^4$ is exactly the Hadamard
(Hadamard--Fischer) determinant inequality, a genuine analytic input rather than
term-counting.
\end{remark}

\section{Refuting the circulated formula}
\label{sec:refute}

A candidate closed form was circulated for the variant with entries in the
\emph{odd-radius} range $\{-(2k-1), \dots, 2k-1\}$:
\[
C(k) := (2k-1)^4 - 2(2k-1)^2 + 1 = \big((2k-1)^2 - 1\big)^2.
\]
We show $C(k)$ is not even an upper bound.

\begin{theorem}[Strict refutation]
For every integer $k \ge 1$,
\[
C(k) = (2k-1)^4 - 2(2k-1)^2 + 1 \;<\; 16\,(2k-1)^4.
\]
\end{theorem}

\begin{proof}
With $t = 2k-1 \ge 1$, the claim is $0 < 15t^4 + 2t^2 - 1$, which holds since
$15t^4 \ge 15$ and $2t^2 \ge 2$.
\end{proof}

Because $H(2k-1)$ is $(2k-1)$-admissible with determinant $16\,(2k-1)^4$, this
exhibits an admissible matrix exceeding $C(k)$ for every $k$.

\begin{theorem}[Failure at $k=1$]
For the range $\{-1,0,1\}$, $C(1) = 0$, yet $H(1)$ is admissible with determinant
$16$.
\end{theorem}

\begin{proof}
$C(1) = 1 - 2 + 1 = 0$; the $\pm 1$ matrix $H(1)$ has determinant $16 > 0$.
\end{proof}

\begin{theorem}[Odd-radius bracket]
For every $k \ge 1$, over $\{-(2k-1), \dots, 2k-1\}$ there is an admissible matrix
of determinant $16\,(2k-1)^4$, and every admissible matrix has determinant at most
$24\,(2k-1)^4$.
\end{theorem}

\section{Applications}

The orthogonality that maximizes the determinant also makes scaled Hadamard
matrices central to error-correcting codes (maximally dissimilar $\pm 1$
codewords, as in deep-space telemetry), to signal processing (the fast
Walsh--Hadamard transform), and to statistical design of experiments (optimal
two-level and Plackett--Burman designs, whose $D$-optimality is exactly the
maximal-determinant condition). The order-$4$ case is the base of all of these.

\section{Discussion and future work}

\begin{conjecture}[Exact bound]
Every $4 \times 4$ real matrix with $|A_{ij}| \le B$ satisfies
$|\det A| \le 16\,B^4$, with equality exactly for scaled Hadamard matrices.
\end{conjecture}

\begin{conjecture}[General even order]
For $4 \mid n$, the maximum determinant with $|A_{ij}| \le B$ equals
$n^{n/2}B^n$, attained iff a Hadamard matrix of order $n$ exists --- linking the
problem to the Hadamard conjecture.
\end{conjecture}

\begin{conjecture}[Non-Hadamard deficit]
For $n \equiv 1,2,3 \pmod 4$ the maximum is strictly below $n^{n/2}B^n$, with the
deficit governed by the Barba and Ehlich--Wojtas bounds scaled by $B^n$.
\end{conjecture}

\begin{conjecture}[Rigidity]
The only order-$4$ maximisers over $\{-B,\dots,B\}$ are the $2^4\cdot 4! = 384$
signed permutations of the scaled Hadamard matrix.
\end{conjecture}

\section{Conclusion}

The maximum determinant of a $4 \times 4$ integer matrix with entries bounded by
$B$ is $16\,B^4$, achieved by a scaled order-$4$ Hadamard matrix whose orthogonal
rows certify extremality. An elementary permutation bound gives the bracket
$16\,B^4 \le M(B) \le 24\,B^4$, closed to the exact value by the Hadamard
inequality. The circulated candidate $(2k-1)^4 - 2(2k-1)^2 + 1$ fails to bound the
family and collapses to $0$ at $k=1$ despite a true maximum of $16$: extremal
values are proved by explicit construction, and false formulas by explicit
counterexample.

\end{document}

