from itertools import permutations
from typing import List

Matrix = List[List[int]]


def leibniz_upper_bound(B: int, n: int = 4) -> int:
    """Universal upper bound n! * B^n from the Leibniz permutation sum."""
    fact = 1
    for i in range(2, n + 1):
        fact *= i
    return fact * B ** n


def hadamard_lower_bound(B: int) -> int:
    """Achievable lower bound 16 * B^4 from the scaled Hadamard matrix."""
    return 16 * B ** 4


def det_leibniz(m: Matrix) -> int:
    """Determinant via the explicit permutation (Leibniz) sum."""
    n = len(m)
    total = 0
    for perm in permutations(range(n)):
        sign, seen = 1, list(perm)
        # inversion-count parity
        inv = sum(1 for i in range(n) for j in range(i + 1, n) if seen[i] > seen[j])
        sign = -1 if inv % 2 else 1
        prod = 1
        for i in range(n):
            prod *= m[i][perm[i]]
        total += sign * prod
    return total


def bracket(B: int) -> tuple:
    """Return (lower, upper) bracket for the maximum determinant M(B)."""
    return hadamard_lower_bound(B), leibniz_upper_bound(B)


if __name__ == "__main__":
    for B in (1, 2, 3, 4):
        lo, hi = bracket(B)
        print(f"B={B}: {lo} <= M(B) <= {hi}")

